DCTCP_PLOT_COLOUR = 'tab:blue'


def plot_flow_size_vs_latency(
    experiment_family, title_addendum, experiment_date,
    ssird_flow_size_fct_s_pairs_list_list,
    xpass_flow_size_fct_s_pairs_list_list,    
    dctcp_flow_size_fct_s_pairs_list_list,    
    x_lim=None, y_lim=None
):

    print([len(flow_size_fct_s_pairs_list) for flow_size_fct_s_pairs_list in ssird_flow_size_fct_s_pairs_list_list])
    print([len(flow_size_fct_s_pairs_list) for flow_size_fct_s_pairs_list in xpass_flow_size_fct_s_pairs_list_list])
    print([len(flow_size_fct_s_pairs_list) for flow_size_fct_s_pairs_list in dctcp_flow_size_fct_s_pairs_list_list])

    assert(len(set([
        len(ssird_flow_size_fct_s_pairs_list_list),
        len(xpass_flow_size_fct_s_pairs_list_list),
        len(dctcp_flow_size_fct_s_pairs_list_list)
    ]))==1)

    num_experiments = len(ssird_flow_size_fct_s_pairs_list_list)

    for i in range(num_experiments):
        ssird_flow_size_fct_s_pairs_list = ssird_flow_size_fct_s_pairs_list_list[i]
        xpass_flow_size_fct_s_pairs_list = xpass_flow_size_fct_s_pairs_list_list[i]
        dctcp_flow_size_fct_s_pairs_list = dctcp_flow_size_fct_s_pairs_list_list[i]

        assert(len(set([
            len(ssird_flow_size_fct_s_pairs_list),
            len(xpass_flow_size_fct_s_pairs_list),
            len(dctcp_flow_size_fct_s_pairs_list)
        ]))==1)
        num_flows = len(ssird_flow_size_fct_s_pairs_list)

        ssird_flow_size_list = [size for size, fct_s in ssird_flow_size_fct_s_pairs_list]
        xpass_flow_size_list = [size for size, fct_s in xpass_flow_size_fct_s_pairs_list]
        dctcp_flow_size_list = [size for size, fct_s in dctcp_flow_size_fct_s_pairs_list]

        ssird_fct_us_list = [fct_s*1000*1000 for size, fct_s in ssird_flow_size_fct_s_pairs_list] 
        xpass_fct_us_list = [fct_s*1000*1000 for size, fct_s in xpass_flow_size_fct_s_pairs_list] 
        dctcp_fct_us_list = [fct_s*1000*1000 for size, fct_s in dctcp_flow_size_fct_s_pairs_list] 

        plt.figure(figsize=(10, 6))
        plt.xlabel(f'Flow Size (Bytes)')
        plt.ylabel('Latency (us)')
        plt.title(f'Flow Size vs Latency {num_flows}flo\n{experiment_family}{title_addendum}\n{experiment_date}')

        plt.plot(ssird_flow_size_list, ssird_fct_us_list, label="SSIRD", linestyle='-', marker='^', color=SSIRD_PLOT_COLOUR, markersize=3)
        # plt.plot(xpass_flow_size_list, xpass_fct_ms_list, label="ExpressPass", linestyle='-', marker='s', color=XPASS_PLOT_COLOUR, markersize=2)
        # plt.plot(dctcp_flow_size_list, dctcp_fct_ms_list, label="DCTCP", linestyle='-', marker='o', color=DCTCP_PLOT_COLOUR, markersize=2)

        plt.legend()

        ax = plt.gca()
        ax.grid(True, which='both')

        if (x_lim is not None):
            ax.set_xlim(x_lim)
        if (y_lim is not None):
            ax.set_ylim(y_lim)

        # ax.set_xscale('log')

        Path(PATH_TO_FLOW_SIZE_VS_LATENCY).mkdir(parents=True, exist_ok=True)
        filename = f"allproto_flowsize_vs_latency_{num_flows}flo_{experiment_family}{title_addendum}_{experiment_date}.png"
        plt.savefig(f"{PATH_TO_FLOW_SIZE_VS_LATENCY}{filename}")
        plt.close()
        # return

